/**
 * Resolves Google Drive image URLs to local paths using the
 * manifest generated by scripts/sync-sheet-images.mjs.
 *
 * At build time, images are downloaded to public/sheets-images/.
 * This module maps the original URLs to those local paths so
 * images load instantly from the bundle instead of hitting Google.
 */

// Vite inlines this JSON at build time. The file always exists (the sync
// script writes at least `{}`), so a static import avoids top-level await,
// which isn't supported by the production build target.
import manifestData from "@/data/sheet-images.json";

const manifest = manifestData || {};

/**
 * Given an image URL (Google Drive or direct), return the local
 * path if available, otherwise return the original URL unchanged.
 */
export function resolveImage(url) {
  if (!url || typeof url !== "string") return url;
  const trimmed = url.trim();

  // Check exact match first
  if (manifest[trimmed]) return manifest[trimmed];

  // Try to extract the googleusercontent direct URL and check that
  const fileMatch = trimmed.match(/drive\.google\.com\/file\/d\/([^/]+)/);
  if (fileMatch) {
    const direct = `https://lh3.googleusercontent.com/d/${fileMatch[1]}`;
    if (manifest[direct]) return manifest[direct];
  }

  const openMatch = trimmed.match(/drive\.google\.com\/open\?id=([^&]+)/);
  if (openMatch) {
    const direct = `https://lh3.googleusercontent.com/d/${openMatch[1]}`;
    if (manifest[direct]) return manifest[direct];
  }

  // No local version — return original
  return trimmed;
}
